{"implementation":"def solve(case):
    lengths = case['lengths']
    scores = case['scores']
    budget = case['budget']
    n = len(lengths)
    dp = [{} for _ in range(n+1)]
    dp[0][0] = (0.0, 0, [])
    def better(score_a, tokens_a, indices_a, state_b):
        score_b, tokens_b, indices_b = state_b
        if score_a != score_b:
            return score_a > score_b
        if tokens_a != tokens_b:
            return tokens_a < tokens_b
        return indices_a < indices_b
    for i in range(n):
        w_i = lengths[i]
        s_i = scores[i]
        for weight, (score, tokens, indices) in dp[i].items():
            if weight not in dp[i+1] or better(score, tokens, indices, dp[i+1][weight]):
                dp[i+1][weight] = (score, tokens, indices)
            new_w = weight + w_i
            if new_w <= budget:
                new_score = score + s_i
                new_tokens = tokens + w_i
                new_indices = indices + [i]
                if new_w not in dp[i+1] or better(new_score, new_tokens, new_indices, dp[i+1][new_w]):
                    dp[i+1][new_w] = (new_score, new_tokens, new_indices)
    best_score, best_tokens, best_indices = None, None, None
    for weight, (score, tokens, indices) in dp[n].items():
        if best_score is None or better(score, tokens, indices, (best_score, best_tokens, best_indices)):
            best_score, best_tokens, best_indices = score, tokens, indices
    if best_score is None:
        return {'selected_indices': [], 'used_tokens': 0, 'summed_score': 0.0}
    return {'selected_indices': best_indices, 'used_tokens': best_tokens, 'summed_score': best_score}"}
